"""Functional utilities.

This module implements the core functional programming helpers used by
``toolz``.  It is intentionally lightweight and contains only the
functions required by the public API.
"""

from functools import reduce, partial
import inspect
import operator
from operator import attrgetter
from importlib import import_module
from textwrap import dedent

from .compatibility import PY3, PY34, PYPY
from .utils import no_default

__all__ = (
    "identity",
    "thread_first",
    "thread_last",
    "memoize",
    "compose",
    "pipe",
    "compose_left",
    "apply",
    "peek",
    "peekn",
    "do",
    "curry",
    "flip",
    "excepts",
    "complement",
    "juxt",
)


# ---------------------------------------------------------------------------
# Basic utilities
# ---------------------------------------------------------------------------

def identity(x):
    """Identity function. Return ``x``.

    >>> identity(3)
    3
    """
    return x


def apply(func, *args, **kwargs):
    """Apply a callable with the provided arguments.

    Equivalent to ``func(*args, **kwargs)``.

    >>> apply(lambda x, y: x + y, 1, 2)
    3
    """
    return func(*args, **kwargs)


def compose_left(*funcs):
    """Compose functions from left to right.

    Returns a callable that applies the functions in order.

    >>> add1 = lambda x: x + 1
    >>> mul2 = lambda x: x * 2
    >>> f = compose_left(add1, mul2)
    >>> f(3)
    8
    """
    if not funcs:
        return identity
    if len(funcs) == 1:
        return funcs[0]
    def composed(x):
        for f in funcs:
            x = f(x)
        return x
    return composed


def peek(func, x):
    """Apply ``func`` to ``x`` for side-effect and return ``x`` unchanged.

    Useful for debugging or logging in a pipeline.

    >>> log = []
    >>> peek(log.append, 10)
    10
    >>> log
    [10]
    """
    func(x)
    return x


def peekn(func, x):
    """Same as :func:`peek` but accepts a function that takes an iterable
    and returns a value; ``x`` is passed through unchanged.

    >>> log = []
    >>> peekn(lambda seq: log.append(list(seq)), [1, 2, 3])
    [1, 2, 3]
    >>> log
    [[1, 2, 3]]
    """
    func(x)
    return x


# ---------------------------------------------------------------------------
# Threading helpers
# ---------------------------------------------------------------------------

def thread_first(val, *forms):
    """Thread value through a sequence of functions/forms.

    >>> def double(x): return 2 * x
    >>> def inc(x):    return x + 1
    >>> thread_first(1, inc, double)
    4
    """
    def evalform_front(val, form):
        if callable(form):
            return form(val)
        if isinstance(form, tuple):
            func, args = form[0], form[1:]
            args = (val,) + args
            return func(*args)
    return reduce(evalform_front, forms, val)


def thread_last(val, *forms):
    """Thread value through a sequence of functions/forms.

    >>> def double(x): return 2 * x
    >>> def inc(x):    return x + 1
    >>> thread_last(1, inc, double)
    4
    """
    def evalform_back(val, form):
        if callable(form):
            return form(val)
        if isinstance(form, tuple):
            func, args = form[0], form[1:]
            args = args + (val,)
            return func(*args)
    return reduce(evalform_back, forms, val)


# ---------------------------------------------------------------------------
# Property helpers
# ---------------------------------------------------------------------------

def instanceproperty(fget=None, fset=None, fdel=None, doc=None, classval=None):
    """Like @property, but returns ``classval`` when used as a class attribute.

    >>> class MyClass(object):
    ...     @instanceproperty(classval='class')
    ...     def val(self):
    ...         return 42
    ...
    >>> MyClass.val
    'class'
    >>> MyClass().val
    42
    """
    if fget is None:
        return partial(instanceproperty, fset=fset, fdel=fdel, doc=doc, classval=classval)
    return InstanceProperty(fget=fget, fset=fset, fdel=fdel, doc=doc, classval=classval)


class InstanceProperty(property):
    """Property that returns ``classval`` when accessed via the class.
    """
    def __init__(self, fget=None, fset=None, fdel=None, doc=None, classval=None):
        self.classval = classval
        super().__init__(fget=fget, fset=fset, fdel=fdel, doc=doc)

    def __get__(self, obj, type=None):
        if obj is None:
            return self.classval
        return super().__get__(obj, type)

    def __reduce__(self):
        state = (self.fget, self.fset, self.fdel, self.__doc__, self.classval)
        return InstanceProperty, state


# ---------------------------------------------------------------------------
# Curry helper
# ---------------------------------------------------------------------------
class curry(object):
    """Curry a callable function.

    Allows partial application of arguments.
    """
    def __init__(self, *args, **kwargs):
        if not args:
            raise TypeError("__init__() takes at least 2 arguments (1 given)")
        func, args = args[0], args[1:]
        if not callable(func):
            raise TypeError("Input must be callable")
        # Unpack partial-like objects
        if (
            hasattr(func, 'func') and hasattr(func, 'args') and hasattr(func, 'keywords')
            and isinstance(func.args, tuple)
        ):
            _kwargs = {}
            if func.keywords:
                _kwargs.update(func.keywords)
            _kwargs.update(kwargs)
            kwargs = _kwargs
            args = func.args + args
            func = func.func
        if kwargs:
            self._partial = partial(func, *args, **kwargs)
        else:
            self._partial = partial(func, *args)

    def __call__(self, *args, **kwargs):
        try:
            return self._partial(*args, **kwargs)
        except TypeError as exc:
            if self._should_curry(args, kwargs, exc):
                return self.bind(*args, **kwargs)
            raise

    def _should_curry(self, args, kwargs, exc=None):
        # Simplified: always allow curry
        return True

    def bind(self, *args, **kwargs):
        return type(self)(self, *args, **kwargs)

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return curry(self, instance)

    def __reduce__(self):
        return _restore_curry, (self.func, self.args, self.keywords)


# ---------------------------------------------------------------------------
# Memoize helper
# ---------------------------------------------------------------------------
@curry
def memoize(func, cache=None, key=None):
    """Cache a function's result for speedy future evaluation.

    >>> def add(x, y):  return x + y
    >>> add = memoize(add)
    >>> add(1, 2)
    3
    """
    cache = cache or {}
    key_func = key or func
    def wrapper(*args, **kwargs):
        k = key_func(*args, **kwargs)
        if k in cache:
            return cache[k]
        result = func(*args, **kwargs)
        cache[k] = result
        return result
    return wrapper


# ---------------------------------------------------------------------------
# Function composition
# ---------------------------------------------------------------------------
class Compose(object):
    def __init__(self, funcs):
        funcs = tuple(reversed(funcs))
        self.first = funcs[0]
        self.funcs = funcs[1:]

    def __call__(self, *args, **kwargs):
        ret = self.first(*args, **kwargs)
        for f in self.funcs:
            ret = f(ret)
        return ret

    def __getstate__(self):
        return self.first, self.funcs

    def __setstate__(self, state):
        self.first, self.funcs = state

    def __name__(self):
        return '_of_'.join(f.__name__ for f in reversed((self.first,) + self.funcs))

    def __doc__(self):
        try:
            return 'lambda *args, **kwargs: ' + '\n'.join(f.__name__ for f in reversed((self.first,) + self.funcs))
        except AttributeError:
            return type(self).__name__


def compose(*funcs):
    """Compose functions to operate in series.

    Returns a function that applies other functions in sequence.

    Functions are applied from right to left:
    ``compose(f, g, h)(x)`` is the same as ``f(g(h(x)))``.
    """
    if not funcs:
        return identity
    if len(funcs) == 1:
        return funcs[0]
    return Compose(funcs)


def pipe(data, *funcs):
    """Pipe a value through a sequence of functions.

    ``pipe(data, f, g, h)`` is equivalent to ``h(g(f(data)))``.
    """
    for f in funcs:
        data = f(data)
    return data


# ---------------------------------------------------------------------------
# Predicate complement
# ---------------------------------------------------------------------------

def complement(func):
    """Convert a predicate function to its logical complement."""
    return compose(operator.not_, func)


# ---------------------------------------------------------------------------
# Juxtapose
# ---------------------------------------------------------------------------
class juxt(object):
    def __init__(self, *funcs):
        if len(funcs) == 1 and not callable(funcs[0]):
            funcs = funcs[0]
        self.funcs = tuple(funcs)

    def __call__(self, *args, **kwargs):
        return tuple(f(*args, **kwargs) for f in self.funcs)


# ---------------------------------------------------------------------------
# Side-effect helper
# ---------------------------------------------------------------------------

def do(func, x):
    """Run ``func`` on ``x`` and return ``x`` unchanged."""
    func(x)
    return x


# ---------------------------------------------------------------------------
# Flip arguments
# ---------------------------------------------------------------------------
@curry
def flip(func, a, b):
    return func(b, a)


# ---------------------------------------------------------------------------
# Exception wrapper
# ---------------------------------------------------------------------------

def return_none(exc):
    return None


class excepts(object):
    def __init__(self, exc, func, handler=return_none):
        self.exc = exc
        self.func = func
        self.handler = handler

    def __call__(self, *args, **kwargs):
        try:
            return self.func(*args, **kwargs)
        except Exception as exc:
            if isinstance(exc, self.exc):
                return self.handler(exc)
            raise


# End of module
